INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('about','About INFOROVA','About the INFOROVA publication','<h2>About us</h2><p>INFOROVA is an independent information website focused on useful, readable and organized content.</p><p>We aim to publish clear articles across jobs, exams and practical topics.</p>');
INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('contact','Contact','Contact INFOROVA','<h2>Contact</h2><p>For editorial or website questions, contact the site administrator through the official contact channel published on this website.</p>');
INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('privacy-policy','Privacy Policy','INFOROVA privacy policy','<h2>Privacy Policy</h2><p>This Privacy Policy explains how INFOROVA (inforova.xyz) collects, uses and protects information when you visit this website.</p><h3>Log Files</h3><p>Like most websites, INFOROVA uses log files. This data may include Internet Protocol (IP) addresses, browser type, Internet Service Provider (ISP), date/time stamp, referring/exit pages, and possibly the number of clicks. This information is used to analyze trends, administer the site, track visitor movement, and gather demographic information, and is not linked to any personally identifiable information.</p><h3>Cookies and Web Beacons</h3><p>INFOROVA uses cookies to store information about visitor preferences and to record user-specific information on which pages the visitor accesses or visits, in order to customize web page content based on visitor browser type or other information the visitor sends via their browser.</p><h3>Google DoubleClick DART Cookie</h3><p>Google is a third-party vendor on this site. Google uses cookies, known as DART cookies, to serve ads to visitors based on their visit to this site and other sites on the Internet. Visitors may opt out of the use of the DART cookie by visiting the Google ad and content network privacy policy at <a href=\"https://policies.google.com/technologies/ads\" target=\"_blank\" rel=\"noopener\">https://policies.google.com/technologies/ads</a>.</p><h3>Third-Party Advertising Partners</h3><p>Some advertisers on this site may use cookies and web beacons. Each advertising partner has its own privacy policy regarding user data. This website has no access to or control over the cookies used by third-party advertisers. Users are advised to consult the respective privacy policies of these third-party ad servers for more information.</p><h3>Children''s Information</h3><p>INFOROVA does not knowingly collect any personal information from children under the age of 13. If you believe your child has provided this kind of information on our website, please contact us immediately.</p><h3>Consent</h3><p>By using this website, you consent to this Privacy Policy and agree to its terms.</p>');
INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('terms','Terms of Use','Terms of use for INFOROVA','<h2>Terms of Use</h2><p>Content is provided for general informational purposes. Verify important dates, eligibility requirements and official notices with the relevant authority.</p>');
INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('disclaimer','Disclaimer','INFOROVA disclaimer','<h2>Disclaimer</h2><p>INFOROVA is an independent publication and is not an official government authority unless explicitly stated. Information can change; readers should check primary sources before making decisions.</p>');
INSERT IGNORE INTO pages(slug,title,meta_description,content_html) VALUES ('cookie-policy','Cookie Policy','INFOROVA cookie policy','<h2>Cookie Policy</h2><p>This site may use essential cookies for functionality and optional cookies from advertising or analytics services where configured.</p>');
INSERT IGNORE INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES (1,'How to Read a Government Job Notice Correctly','how-to-read-a-government-job-notice','A simple guide to checking eligibility, dates, documents and application instructions.','<p>Government job notices can contain many details. Start by checking the official notice date and application deadline.</p><h2>Check the essentials</h2><ul><li>Eligibility and age requirements</li><li>Application opening and closing dates</li><li>Required documents</li><li>Official application website</li></ul><p>Always verify the final information from the issuing authority.</p>','published',NOW());
INSERT IGNORE INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES (2,'Exam News: What to Check Before Applying','exam-news-what-to-check-before-applying','Key items to verify before submitting an exam application.','<p>Before submitting an application, confirm the official notice, fee information, deadlines and required documents.</p><h2>Keep a checklist</h2><p>Save the official notice and record the important dates in your calendar.</p>','published',NOW());
INSERT IGNORE INTO articles(category_id,title,slug,excerpt,content_html,status,published_at) VALUES (3,'A Practical Weekly Exam Preparation Plan','practical-weekly-exam-preparation-plan','A flexible study structure for reviewing topics, practicing questions and tracking progress.','<p>A useful plan balances learning, practice and revision.</p><h2>Weekly structure</h2><p>Choose a small number of topics, practice questions regularly and reserve time to review mistakes.</p>','published',NOW());
